def P(text,sty='Normal'):
 sub=str.maketrans('₀₁₂₃₄₅₆₇₈₉ᵢⱼ','0123456789ij')
 sup=str.maketrans('⁰¹²³⁴⁵⁶⁷⁸⁹⁻⁺ⁿ','0123456789-+n')
 text=re.sub('[₀₁₂₃₄₅₆₇₈₉ᵢⱼ]+',lambda m:'<sub>'+m[0].translate(sub)+'</sub>',text)
 text=re.sub('[⁰¹²³⁴⁵⁶⁷⁸⁹⁻⁺ⁿ]+',lambda m:'<super>'+m[0].translate(sup)+'</super>',text)
 return Paragraph(text,styles[sty])
def table(headers,data,widths=None,size=9):
 a=[[P(str(v),'TH') for v in headers]]+[[P(str(v),'Small') for v in r] for r in data]
 t=Table(a,colWidths=widths,repeatRows=1,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#283D57')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F0F3F7')]),('LINEBELOW',(0,0),(-1,0),.5,colors.HexColor('#283D57'))]))
 for cell in a[0]:cell.style=ParagraphStyle('TH',parent=styles['Small'],textColor=colors.white,fontName='ArialBold')
 return t
