 w=[1/a**2 for a in u];return [sum(w),sum(a*b for a,b in zip(w,x)),sum(a*b for a,b in zip(w,y)),sum(a*b*b for a,b in zip(w,x)),sum(a*b*c for a,b,c in zip(w,x,y))]
